pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 a, uint256 b) internal {
        try c.SetMinSum(a) {} catch { return; }
        uint256 mid;
        try c.MinSum() returns (uint256 __r) { mid = __r; } catch { return; }
        try c.SetMinSum(b) {} catch { return; }
        uint256 fin;
        try c.MinSum() returns (uint256 __r) { fin = __r; } catch { return; }
        assertTrue(fin == b);
    }

    function testFuzz_run(uint256 a, uint256 b) public {
        _run(a, b);
    }

    receive() external payable {}
}
